function renderHome(){
 if(HOME_DESKTOP.matches)return renderHomeDesktop();
 const arriving=state.mode==='chegando'&&!readonly(),leaving=state.mode==='saindo'&&!readonly();
 const title=readonly()?`Conheça ${state.city}`:arriving?'Prepare sua chegada':leaving?'Organize sua mudança':`Perto de você, em ${state.city}`;
 const subtitle=arriving?`${countDays(state.arrival)} dias para chegar · ${dateLabel(state.arrival)}`:leaving?`${countDays(state.leaveDate)} dias para sua mudança para ${state.dest}`:'Serviços, oportunidades e indicações de militares e famílias.';
 let h=`<div class="page-head"><div><h1>${esc(title)}</h1><p>${esc(subtitle)}</p></div></div><div class="home-top"><md-filled-tonal-button id="home-search" class="home-search-button" data-action="search" aria-label="Buscar no Bivaque">${icon('search','icon')}<span>${arriving?'Escola, bairro, imóvel':'Indicações, desapegos, imóveis'}</span></md-filled-tonal-button><nav class="intent-grid" aria-label="Áreas">${(arriving?[['apartment','Imóveis','imovel'],['storefront','Negócios','biz'],['sell','Desapegos','desapego'],['volunteer_activism','Indicações','ind']]:[['storefront','Negócios','biz'],['sell','Desapegos','desapego'],['apartment','Imóveis','imovel'],['volunteer_activism','Indicações','ind']]).map(([ic,label,v])=>`<button type="button" class="intent" data-action="intent" data-value="${v}">${icon(ic)}<span>${label}</span></button>`).join('')}</nav></div>`;
 h+=readonlyHtml();
 h+=homeResumeHtml();
 if((arriving||leaving)&&state.plan[state.mode])h+=renderPlan(state.mode);
 if(!readonly()&&state.mode==='moro'&&state.incoming)h+=`<div class="context-strip"><button type="button" data-action="nav" data-value="comunidade">${icon('flight_land')}<span class="grow"><b>${state.incoming} famílias estão chegando</b> · uma indicação sua pode ajudar.</span>${icon('chevron_right')}</button></div>`;
 h+=homeGroupsBlock();
 const items=cityItems().filter(x=>x.status==='active').sort((a,b)=>b.createdAt-a.createdAt).slice(0,4);
 h+=`<section class="section">${sectionTitle(arriving?'Para a casa nova':'Desapegos e imóveis','Ver todos','catalog-all')}<div class="carousel">${items.map(photoCard).join('')}</div>${!items.length?empty('As primeiras oportunidades aparecem aqui','Quando alguém publicar nesta cidade, você poderá consultar e entrar em contato.','sell',readonly()?'':'create-item',readonly()?'':'Anunciar desapego'):''}</section>`;
 const biz=cityBiz().filter(b=>!b.spon).sort((a,b)=>b.recN-a.recN).slice(0,3);
 h+=`<section class="section">${sectionTitle('Negócios indicados','Ver todos','businesses')}<div class="carousel biz-cards">${biz.map(businessCard).join('')}</div>${!biz.length?empty('Ainda sem negócios cadastrados','As indicações da comunidade ajudarão a formar o guia de serviços.','storefront'):''}</section>`;
 const sponsored=cityBiz().find(b=>b.spon&&b.claimed!==false);if(sponsored)h+=`<section class="sponsored-section"><div class="row between" style="margin-bottom:10px"><h3>Destaque na cidade</h3>${pill('Patrocinado','ad')}</div><button type="button" class="list-row" data-action="open-biz" data-value="${sponsored.id}" style="padding:0">${image(sponsored.photos?.[0])?`<img class="list-photo" src="${image(sponsored.photos[0])}" alt="">`:''}<span class="txt"><b>${esc(sponsored.name)}</b><small>${esc(sponsored.disc||sponsored.cat)}</small></span>${icon('chevron_right')}</button></section>`;
 if(!readonly())h+=`<div class="context-strip readonly">${icon('add_business')}<span class="grow"><b>Tem um negócio?</b><br>Crie sua página e receba pedidos da comunidade.</span>${btn(state.myBiz?.live?'Minha página':'Criar página','my-biz','','text')}</div>`;
 const qs=cityAsks().filter(q=>q.status==='open').sort((a,b)=>a.answers.length-b.answers.length).slice(0,2);
 h+=`<section class="section">${sectionTitle('A comunidade procura','Ver perguntas','nav','comunidade')}${qs.length?`<div class="list">${qs.map(questionRow).join('')}</div>`:empty('Uma pergunta pode ajudar muita gente','Busque uma indicação ou compartilhe uma dúvida com sua cidade.','forum',readonly()?'':'ask',readonly()?'':'Pedir indicação')}</section>`;
 const events=state.events.filter(e=>e.city===state.city&&e.date>=dateISO()).sort((a,b)=>a.date.localeCompare(b.date)).slice(0,2);
 if(events.length)h+=`<section class="section">${sectionTitle('Encontros próximos','Agenda','agenda')}<div class="list">${events.map(eventRow).join('')}</div></section>`;
 h+=`<section class="section">${sectionTitle(`Guia de ${state.city}`,'Abrir guia','guide')}<button type="button" class="list-row list" data-action="guide">${icon('map')}<span class="txt"><b>Organize moradia, mudança e serviços</b><small>Um roteiro prático para se estabelecer na cidade.</small></span>${icon('chevron_right')}</button></section>`;
 return h;
}
function renderPlan(kind,full=false){const steps=state.plan[kind],n=steps.filter(x=>x.done).length;return `<section class="section"><div class="progress-wrap"><div class="row between"><h3>${kind==='chegando'?'Sua chegada':'Sua saída'}</h3><span class="small muted">${n} de ${steps.length}</span></div><md-linear-progress value="${n/steps.length}" aria-label="${n} de ${steps.length} etapas concluídas"></md-linear-progress><div class="stack" style="gap:6px">${steps.slice(0,full?steps.length:3).map(x=>`<div class="plan-row"><md-checkbox ${x.done?'checked':''} aria-label="Marcar ${esc(x.t)} como concluído" data-action="plan-check" data-value="${kind}|${x.id}"></md-checkbox><button type="button" data-action="plan-go" data-value="${kind}|${x.id}"><b>${esc(x.t)}</b><small>${esc(x.s)}</small></button>${icon('chevron_right')}</div>`).join('')}</div>${full?'':btn('Ver plano completo','plan',kind,'text','checklist')}</div></section>`;}
// "Continue de onde parou": o mesmo na Início do celular e na do desktop (Rodada 13).
function homeResumeHtml(){if(readonly()||state.lastViewed?.city!==state.city)return '';const l=state.lastViewed,x=l.type==='item'?itemById(l.id):l.type==='biz'?bizById(l.id):askById(l.id);return x?`<div class="context-strip"><button type="button" data-action="resume" data-value="${l.type}|${l.id}">${icon('history')}<span class="grow"><b>Continue de onde parou</b><br>${esc(x.title||x.name||x.q)}</span>${icon('chevron_right')}</button></div>`:'';}
